from enum import Enum
import json
from pydantic import BaseModel
from pydantic_ai import Agent, RunContext

class RiskClass(str, Enum):
    READ = 'read'
    WRITE = 'write'
    EXEC = 'exec'
    EXTERNAL = 'external'

class Mode(str, Enum):
    DISCUSS = 'discuss'
    PLAN = 'plan'
    INTERACTIVE = 'interactive'
    AUTO = 'auto'
    CUSTOM = 'custom'

_RISK_TABLE = {
    'read_file': RiskClass.READ,
    'batch_read': RiskClass.READ,
    'write_file': RiskClass.WRITE,
    'replace_text': RiskClass.WRITE,
    'replace_function': RiskClass.WRITE,
    'add_import': RiskClass.WRITE,
    'delete_file': RiskClass.WRITE,
    'shell': RiskClass.EXEC,
}

def classify(tool_name: str) -> RiskClass:
    return _RISK_TABLE.get(tool_name, RiskClass.EXEC)

def is_consequential(risk: RiskClass) -> bool:
    return risk != RiskClass.READ

class Decision(BaseModel):
    allowed: bool
    reason: str
    needs_user: bool
    rule: str

def _authorize(tool_name: str, mode: Mode = Mode.INTERACTIVE) -> Decision:
    risk = classify(tool_name)
    if risk == RiskClass.READ:
        return Decision(allowed=True, reason='auto-pass', needs_user=False, rule='READ')
    if mode in (Mode.AUTO, Mode.CUSTOM):
        return Decision(allowed=True, reason=f'auto-allowed in {mode.value}', needs_user=False, rule=f'{mode.value}-allow')
    return Decision(allowed=False, reason=f'{risk.value} risk needs approval in {mode.value} mode', needs_user=True, rule=f'{risk.value}+{mode.value}-deny')

class PermissionDenied(Exception):
    """Raised for non-READ tools in INTERACTIVE mode; surfaces as tool-error to LLM."""

class AgentDeps(BaseModel):
    mode: Mode = Mode.INTERACTIVE

agent = Agent('test', deps_type=AgentDeps)

@agent.tool
def safe_write(ctx: RunContext[AgentDeps], path: str, content: str) -> str:
    d = _authorize('write_file', ctx.deps.mode)
    if not d.allowed:
        raise PermissionDenied(json.dumps({'error': 'denied', 'reason': d.reason, 'rule': d.rule}))
    return f'wrote {path}'

